INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28401, 'Colossians 3:17', 'Colossians', 3, 17, '&nbsp;او هر څۀ چې تاسو کوئ، هغه کۀ تاسو خبرې کوئ يا څۀ کار، هر څۀ د مالِک عيسىٰ په نوم کوئ او د هغۀ په وسيله د خُدائ پلار شُکر ادا کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28402, 'Colossians 3:18', 'Colossians', 3, 18, '&nbsp;اے ميرمنو، تاسو د خپلو خاوندانو تابعدارې اوسئ ځکه چې دا په مالِک کښې ستاسو فرض دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28403, 'Colossians 3:19', 'Colossians', 3, 19, '&nbsp;اے خاوندانو، د خپلو ښځو سره مينه کوئ او د هغوئ سره ترخيږئ مه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28404, 'Colossians 3:20', 'Colossians', 3, 20, '&nbsp;اے بچو، د مور پلار هره خبره منئ ځکه چې په دې مالِک خُدائ خوشحاليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28405, 'Colossians 3:21', 'Colossians', 3, 21, '&nbsp;اے پلارانو، خپل بچى مۀ تنګوئ، هسې نه چې هغوئ زړۀ بائيلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28406, 'Colossians 3:22', 'Colossians', 3, 22, '&nbsp;اے نوکرانو، تاسو د خپلو دُنياوى مالِکانو په هر څۀ کښې تابعدارى کوئ، او دا نۀ صرف د هغوئ په موجودګۍ کښې چې هغوئ خوشحاله کړئ، بلکې د زړۀ د اخلاصه او د مالِک د احترام دپاره يې کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28407, 'Colossians 3:23', 'Colossians', 3, 23, '&nbsp;هر څۀ چې تاسو کوئ د زړۀ په مينه يې کوئ لکه چې دا تاسو د مالِک دپاره کوئ، او نۀ چې د بنى آدمو دپاره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28408, 'Colossians 3:24', 'Colossians', 3, 24, '&nbsp;ځکه چې تاسو ته پته ده چې د مالِک د طرف نه به د دې په اجر کښې تاسو ته ميراث مِلاو شى. تاسو د مالِک مسيح خِدمت کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28409, 'Colossians 3:25', 'Colossians', 3, 25, '&nbsp;ځکه چې څوک بد کوى هغۀ ته به د خپلې بدۍ سزا مِلاو شى، ځکه چې خُدائ پاک د چا طرفدارے هم نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28410, 'Colossians 4:1', 'Colossians', 4, 1, '&nbsp;اے مالِکانو، د خپلو نوکرانو سره د عدل او اِنصاف سلوک کوئ ځکه چې تاسو ته پته ده چې په آسمان کښې ستاسو هم يو مالِک شته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28411, 'Colossians 4:2', 'Colossians', 4, 2, '&nbsp;خپل ځانونه په دُعا کښې مشغول کړئ او بېدار اوسئ او شُکر ګزارى کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28412, 'Colossians 4:3', 'Colossians', 4, 3, '&nbsp;او مونږ دپاره هم دُعا کوئ چې خُدائ پاک مونږ ته د کلام دپاره ور کولاو کړى چې مونږ د مسيح هغه راز بيان کړُو چې د کوم په سبب زۀ قېد کښې يم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28413, 'Colossians 4:4', 'Colossians', 4, 4, '&nbsp;دُعا کوئ چې زۀ د هغه کلام داسې وضاحت وکړم څنګه چې ما له کول په کار دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28414, 'Colossians 4:5', 'Colossians', 4, 5, '&nbsp;د بې‌ايمانانو سره د هوښيارتيا سلوک کوئ او د هرې موقعې نه فائده اخلئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28415, 'Colossians 4:6', 'Colossians', 4, 6, '&nbsp;ستاسو کلام دې همېشه د فضل نه ډک او خوندور وى چې تاسو هر چا ته مناسب جواب ورکولے شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28416, 'Colossians 4:7', 'Colossians', 4, 7, '&nbsp;تخيکوس به تاسو ته زما په حقله ټولې خبرې وکړى. هغه زمونږ ګران ورور، وفادار خِدمتګار او د مالِک په کار کښې زمونږ ملګرے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28417, 'Colossians 4:8', 'Colossians', 4, 8, '&nbsp;ما هغه تاسو ته د دې مقصد دپاره درولېږلو چې تاسو زمونږ په حال خبر کړى او چې هغه ستاسو زړونو له ډاډګيرنه ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28418, 'Colossians 4:9', 'Colossians', 4, 9, '&nbsp;هغۀ سره زمونږ خوږ ايماندار ورور اونيسيموس درځى څوک چې ستاسو نه يو دے. هغوئ به تاسو ته د دې ځائ په حقله ټولې خبرې بيان کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28419, 'Colossians 4:10', 'Colossians', 4, 10, '&nbsp;اريسترخوس چې ما سره قېدى دے، سلام درلېږى، او دغه شان د برنباس تربور مرقوس هم، د چا په حقله چې تاسو ته حکم درکړے شوے وو چې کۀ هغه تاسو له راغلو نو هرکلے يې وکړئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28420, 'Colossians 4:11', 'Colossians', 4, 11, '&nbsp;او عيسىٰ چې ورته يوستوس وائى هغه هم درته سلام وائى. د يهوديانو نه صرف دا درې کسان دى چې د خُدائ پاک د بادشاهۍ په کار کښې زما ملګرى دى او په هغوئ زما لويه تسلى ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28421, 'Colossians 4:12', 'Colossians', 4, 12, '&nbsp;اِپفراس چې ستاسو نه يو دے او د عيسىٰ مسيح خادِم دے هغه هم تاسو ته سلام وائى. هغه همېشه تاسو دپاره لاس په دُعا دے چې ستاسو ايمان مضبوط شى، او د خُدائ پاک د پوره مرضۍ په مطابق خپل ژوند تېر کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28422, 'Colossians 4:13', 'Colossians', 4, 13, '&nbsp;زۀ د هغۀ ګواهى ورکوم چې هغه ستاسو دپاره او د لوديکيه او د هيراپولس د خلقو دپاره ډېره زياته خوارى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28423, 'Colossians 4:14', 'Colossians', 4, 14, '&nbsp;زمونږ خوږ ملګرى او طبيب لوقا او ديماس درته سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28424, 'Colossians 4:15', 'Colossians', 4, 15, '&nbsp;د لوديکيه وروڼو او خوېندو او نِمفا ته او د هغې په کور کښې د جماعت خلقو ته زما سلام ووايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28425, 'Colossians 4:16', 'Colossians', 4, 16, '&nbsp;نو کله چې تاسو دا خط ولولئ، نو بيا دا د لوديکيې جماعت ته ولېږئ چې هغوئ يې هم ولولى. او تاسو دا خط کوم چې ما هغوئ ته وليکلو ولولئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28426, 'Colossians 4:17', 'Colossians', 4, 17, '&nbsp;او ارخيپوس ته ووايئ چې، ”کوم خِدمت چې په مالِک کښې تا ته سپارلے شوے دے، هغه پوره کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28427, 'Colossians 4:18', 'Colossians', 4, 18, '&nbsp;زۀ پولوس په خپل لاس تاسو ته سلام ليکم. زما په لاس پښو کښې زولنۍ مۀ هېروئ او په تاسو دې د خُدائ پاک فضل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28428, '1 Thessalonians 1:1', '1 Thessalonians', 1, 1, '&nbsp;د پولوس، سيلوانوس او د تيموتيوس د طرف نه، د تِسالونيکيانو جماعت دپاره خط کوم چې د خُدائ پلار او په مالِک عيسىٰ مسيح کښې دے. په تاسو دې فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28429, '1 Thessalonians 1:2', '1 Thessalonians', 1, 2, '&nbsp;ستاسو ټولو دپاره مونږ همېشه د خُدائ پاک شُکر کوُو او هر وخت تاسو په خپلو دُعاګانو کښې يادوو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28430, '1 Thessalonians 1:3', '1 Thessalonians', 1, 3, '&nbsp;مونږ هر وخت د خپل خُدائ پاک او پلار په حضور کښې ستاسو د ايمان کار او ستاسو مينه ناک خِدمت او ستاسو کلک اُميد چې په مالِک عيسىٰ مسيح دے هغه يادوو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28431, '1 Thessalonians 1:4', '1 Thessalonians', 1, 4, '&nbsp;اے وروڼو او خوېندو، مونږ پوهيږو چې تاسو په خُدائ پاک ګران يئ او هغۀ تاسو غوره کړى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28432, '1 Thessalonians 1:5', '1 Thessalonians', 1, 5, '&nbsp;ځکه چې زمونږ زيرے تاسو ته صرف په خبرو نۀ دے راغلے بلکې په قدرت سره، په روحُ القُدس سره او په پوره اعتماد راغلے دے. تاسو ته پته ده چې مونږ ستاسو په مينځ کښې ستاسو دپاره څنګه ژوند تېر کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28433, '1 Thessalonians 1:6', '1 Thessalonians', 1, 6, '&nbsp;او تاسو زمونږ او د مالِک په نقش قدم ژوند اختيار کړو او د سختو تکليفونو باوجود بيا هم تاسو کلام په خوشحالۍ سره د روحُ القُدس په وسيله قبول کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28434, '1 Thessalonians 1:7', '1 Thessalonians', 1, 7, '&nbsp;او داسې تاسو د ټولو ايماندارانو دپاره چې په مِکدونيه او اخيه کښې دى، يو مثال وګرځېدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28435, '1 Thessalonians 1:8', '1 Thessalonians', 1, 8, '&nbsp;ځکه چې ستاسو په وجه نۀ يواځې په مِکدونيه او په اخيه کښې د مالِک کلام خور شو بلکې په خُدائ پاک ستاسو ايمان په هر ځائ کښې داسې مشهور شو چې د دې په حقله زمونږ د وينا څۀ حاجت پاتې نۀ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28436, '1 Thessalonians 1:9', '1 Thessalonians', 1, 9, '&nbsp;ځکه چې د هغه مُلکونو خلقو په خپله د هغه هرکلى په حقله بيان وکړو، کوم چې ستاسو په مينځ کښې زمونږ وشو، او چې تاسو څنګه د بُتانو نه د ژوندى او حقيقى خُدائ پاک خِدمت کولو ته راواوړېدئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28437, '1 Thessalonians 1:10', '1 Thessalonians', 1, 10, '&nbsp;او چې د آسمان نه د هغۀ د زوئ د راتلو اِنتظار وکړئ څوک چې هغۀ د مړو نه بيا راژوندے کړے دے يعنې عيسىٰ، څوک چې به مونږ د راتلونکى غضب نه بچ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28438, '1 Thessalonians 2:1', '1 Thessalonians', 2, 1, '&nbsp;اے وروڼو او خوېندو، تاسو ته په خپله پته ده چې تاسو ته زمونږ راتلل بې‌فائدې نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28439, '1 Thessalonians 2:2', '1 Thessalonians', 2, 2, '&nbsp;خو اګر کۀ چې مونږ په فيليپى کښې ډېر وکړېدو او بې‌عزته کړے شُو څنګه چې تاسو ته پته ده خو بيا هم مونږ په خُدائ پاک کښې دا زړۀ ورتيا وموندله چې تاسو ته مو د ډېرو مخالفتونو باوجود د خُدائ پاک زيرے درورسولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28440, '1 Thessalonians 2:3', '1 Thessalonians', 2, 3, '&nbsp;ځکه دا دعوت چې مونږ ورکوو دا د غلط يا ناپاک نيت نه نۀ دے او نۀ مونږ ستاسو د دوکه کولو کوشش کوُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28441, '1 Thessalonians 2:4', '1 Thessalonians', 2, 4, '&nbsp;بلکې څنګه چې خُدائ پاک مونږ د دې لائق وګڼلو او زيرے يې راته وسپارلو، هم دغه شان يې مونږ بيانوو، اګر چې دا مونږ د بنى آدمو د خوشحالولو دپاره نه بلکې د خُدائ پاک د خوشحالولو دپاره بيانوو، څوک چې زمونږ زړونه آزمائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28442, '1 Thessalonians 2:5', '1 Thessalonians', 2, 5, '&nbsp;ځکه چې تاسو ته پته ده او خُدائ پاک هم زمونږ ګواه دے چې نۀ خو مونږ په خپلو خبرو کښې خوشامندى کړې ده او نۀ مو څۀ لالچ کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28443, '1 Thessalonians 2:6', '1 Thessalonians', 2, 6, '&nbsp;او نۀ مونږ د خلقو نه د عزت طمع کوُو، نۀ ستاسو نه، او نۀ د بل چا نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28444, '1 Thessalonians 2:7', '1 Thessalonians', 2, 7, '&nbsp;اګر چې د مسيح د رسولانو په توګه مونږ په تاسو بوج اچولے شو، خو مونږ ستاسو په مينځ کښې داسې نرمى وکړه لکه څنګه چې يوه مور د غېږې بچى له پئ ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28445, '1 Thessalonians 2:8', '1 Thessalonians', 2, 8, '&nbsp;مونږ تاسو سره دومره مينه وکړه چې نۀ يواځې د خُدائ پاک زيرے مو تاسو سره شريک کړو بلکې خپل ځانونه مو هم ستاسو دپاره قربان کړل، ځکه چې تاسو په مونږ ډېر ګران وئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28446, '1 Thessalonians 2:9', '1 Thessalonians', 2, 9, '&nbsp;اے وروڼو او خوېندو، تاسو ته به زمونږ خوارى او تکليفونه ياد وى چې مونږ شپه او ورځ محنت وکړو او په تاسو مو بوج وانۀ چولو چې مونږ تاسو ته د خُدائ پاک زيرے اورولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28447, '1 Thessalonians 2:10', '1 Thessalonians', 2, 10, '&nbsp;تاسو ګواه يئ او خُدائ پاک هم ګواه دے چې تاسو ايماندارانو سره زمونږ سلوک څنګه د پاکوالى، د صداقت او د بې‌عېبۍ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28448, '1 Thessalonians 2:11', '1 Thessalonians', 2, 11, '&nbsp;څنګه چې تاسو ته پته ده چې مونږ تاسو هر يو سره داسې سلوک وکړو څنګه چې يو پلار د خپلو بچو سره کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28449, '1 Thessalonians 2:12', '1 Thessalonians', 2, 12, '&nbsp;تاسو ته به مو صلاح او ډاډګيرنه درکوله او درباندې به مو زور اچولو چې داسې ژوند تېر کړئ چې د خُدائ پاک خوښ وى، چا چې تاسو خپلې بادشاهۍ او لويئ ته رابللى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28450, '1 Thessalonians 2:13', '1 Thessalonians', 2, 13, '&nbsp;او د دې دپاره مونږ هم هر وخت د خُدائ پاک شُکر کوُو چې کله تاسو ته د خُدائ پاک کلام درورسېدو کوم چې تاسو زمونږ نه اورېدلے دے، نو تاسو دا قبول کړو د بنى آدم د کلام په طور نه بلکې د حقيقت په طور مو قبول کړو چې دا د خُدائ پاک کلام دے، او چې دا تاسو ايماندارانو کښې کار هم کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28451, '1 Thessalonians 2:14', '1 Thessalonians', 2, 14, '&nbsp;اے وروڼو او خوېندو، تاسو د خُدائ پاک د هغه جماعتونو په نقش قدم شوئ کوم چې په يهوديه کښې په عيسىٰ مسيح کښې دى. ځکه چې تاسو هم د خپل قام د خلقو نه هغه تکليفونه وزغمل کوم چې هغوئ ته د يهوديانو نه رسېدلى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28452, '1 Thessalonians 2:15', '1 Thessalonians', 2, 15, '&nbsp;چا چې مالِک عيسىٰ او نبيان دواړه ووژل او مونږ يې هم وشړلو. هغوئ خُدائ پاک خفه کوى او د هر چا مخالفت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28453, '1 Thessalonians 2:16', '1 Thessalonians', 2, 16, '&nbsp;ځکه چې هغوئ مونږ غېر‌يهوديانو ته د خلاصون د پېغام ورکولو نه منع کوى. په دې طريقه هغوئ مسلسل د خپلو ګناهونو پيالۍ تر مورګو ډکوى، او آخر پرې د خُدائ پاک غضب نازل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28454, '1 Thessalonians 2:17', '1 Thessalonians', 2, 17, '&nbsp;اے زما وروڼو او خوېندو، کله چې مونږ د لږې مودې دپاره ستاسو نه په جسمانى توګه جدا شُو نه چې د زړۀ نه، نو مونږ نور هم ډېر په شوق سره ستاسو د بيا ليدلو کوشش کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28455, '1 Thessalonians 2:18', '1 Thessalonians', 2, 18, '&nbsp;ځکه چې مونږ ټولو دا غوښتل چې ستاسو خوا له در شُو خو ما پولوس بار بار د راتلو کوشش وکړو خو شېطان زمونږ لار ونيوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28456, '1 Thessalonians 2:19', '1 Thessalonians', 2, 19, '&nbsp;د مالِک عيسىٰ مسيح په حضور کښې کله چې هغه بيا راشى زمونږ اُميد او خوشحالۍ او د فخر تاج څۀ دے؟ ولې هغه تاسو نۀ يئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28457, '1 Thessalonians 2:20', '1 Thessalonians', 2, 20, '&nbsp;آو، هم تاسو زمونږ جلال او خوشحالى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28458, '1 Thessalonians 3:1', '1 Thessalonians', 3, 1, '&nbsp;نو کله چې مونږ نور دا برداشت نۀ کړے شو، نو مونږ په اتينيه کښې د يواځې پاتې کېدو فېصله وکړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28459, '1 Thessalonians 3:2', '1 Thessalonians', 3, 2, '&nbsp;نو مونږ تيموتيوس چې زمونږ ورور او د مسيح په زېرى کښې د خُدائ پاک خادِم دے د دې دپاره درولېږلو چې هغه تاسو مضبوط کړى او تاسو له په ايمان کښې ډاډګيرنه درکړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28460, '1 Thessalonians 3:3', '1 Thessalonians', 3, 3, '&nbsp;نو چې څوک د دې مصيبتونو په وجه خطا نۀ شئ، ځکه چې تاسو ته پته ده چې دا مصيبتونه زمونږ په نصيب کښې ليکلے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28461, '1 Thessalonians 3:4', '1 Thessalonians', 3, 4, '&nbsp;په حقيقت کښې کله چې مونږ تاسو سره وُو نو مونږ تاسو ته ووئيل چې په مونږ به دا تکليفونه ضرور راځى او دا هم دغه شان وشو لکه څنګه چې تاسو ته ښۀ پته ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28462, '1 Thessalonians 3:5', '1 Thessalonians', 3, 5, '&nbsp;په دې وجه کله چې ما دا نور زيات برداشت نۀ کړو نو ستاسو د ايمان د حال معلومولو دپاره مې تيموتيوس درولېږلو ځکه چې زۀ يرېدلم چې هسې نه چې شېطان تاسو آزمائيلى يئ او زمونږ محنت بې‌فائدې شوے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28463, '1 Thessalonians 3:6', '1 Thessalonians', 3, 6, '&nbsp;خو تيموتيوس اوس له تاسو نه مونږ له واپس راغلو او ستاسو د ايمان او د مينې ښۀ زيرے يې راوړلو. او مونږ ته يې دا هم ووې چې تاسو تل زمونږ خير غواړئ او زمونږ د ليدو په خواهش کښې يئ لکه څنګه چې مونږ ستاسو د ليدو خواهش کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28464, '1 Thessalonians 3:7', '1 Thessalonians', 3, 7, '&nbsp;نو په دې وجه اے وروڼو او خوېندو، مونږ د خپلو ټولو کړاونو او مصيبتونو باوجود ستاسو د ايمان په وجه تسلى وموندله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28465, '1 Thessalonians 3:8', '1 Thessalonians', 3, 8, '&nbsp;خو اوس مونږ حقيقت کښې ژوندى يُو ځکه چې تاسو په مالِک کښې مضبوط ولاړ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28466, '1 Thessalonians 3:9', '1 Thessalonians', 3, 9, '&nbsp;مونږ بيا څنګه ستاسو دپاره د خُدائ پاک شُکر وکړُو د هغه خوشحالۍ په بدل کښې کومه چې ستاسو په وجه مونږ ته د خُدائ پاک په حضور کښې حاصله شوې ده؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28467, '1 Thessalonians 3:10', '1 Thessalonians', 3, 10, '&nbsp;مونږ شپه او ورځ د زړۀ نه ډېره دُعا کوُو چې مونږ تاسو بيا ووينو او ستاسو د ايمان کموالے پوره کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28468, '1 Thessalonians 3:11', '1 Thessalonians', 3, 11, '&nbsp;زمونږ لاره دې اوس زمونږ خُدائ پاک او پلار او زمونږ مالِک عيسىٰ مسيح په خپله ستاسو په طرف سمه کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28469, '1 Thessalonians 3:12', '1 Thessalonians', 3, 12, '&nbsp;او مالِک دې ستاسو مينه د يو بل او د ټولو دپاره داسې ډېره او مضبوطه کړى لکه څنګه چې زمونږ مينه ستاسو سره ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28470, '1 Thessalonians 3:13', '1 Thessalonians', 3, 13, '&nbsp;نو هغه دې ستاسو زړونه مضبوط، بې‌عېبه او مقدس کړى، کله چې تاسو زمونږ د خُدائ پاک او پلار په وړاندې ودرېږئ، کله چې مالِک عيسىٰ د خپلو مقدسينو سره دوباره واپس راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28471, '1 Thessalonians 4:1', '1 Thessalonians', 4, 1, '&nbsp;لنډه دا چې اے وروڼو او خوېندو، مونږ تاسو ته د مالِک عيسىٰ په نوم مِنت کوُو چې تاسو داسې چال چلن کوئ په کوم چې خُدائ پاک خوشحاليږى، لکه څنګه چې مونږ تاسو له تعليم درکړے دے. تاسو دغه شان کوئ، خو مونږ دا ستاسو د ترقۍ دپاره وايو چې نور هم دغه شان کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28472, '1 Thessalonians 4:2', '1 Thessalonians', 4, 2, '&nbsp;ځکه چې تاسو ته د هغه تعليماتو پته ده کوم چې مونږ تاسو له د مالِک عيسىٰ په اختيار درکړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28473, '1 Thessalonians 4:3', '1 Thessalonians', 4, 3, '&nbsp;ځکه چې د خُدائ پاک مرضى دا ده چې تاسو پاک شئ، يعنې د زناکارۍ نه ځان وساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28474, '1 Thessalonians 4:4', '1 Thessalonians', 4, 4, '&nbsp;او تاسو هر يو دا خبره زده کړئ چې څنګه خپل ځان په پاکوالى او عزت سره قابو وساتئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28475, '1 Thessalonians 4:5', '1 Thessalonians', 4, 5, '&nbsp;نۀ د شهوت په جوش سره، او نۀ لکه د هغه بې‌دينو په شان څوک چې خُدائ پاک نۀ پېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28476, '1 Thessalonians 4:6', '1 Thessalonians', 4, 6, '&nbsp;او په دې معامله کښې دې څوک د خپل ورور په حق تجاوز نۀ کوى او نۀ دې د هغۀ سره دوکه کوى. ځکه چې مالِک به هغه ټولو خلقو له سزا ورکړى څوک چې داسې کارونه کوى، لکه څنګه چې مونږ تاسو ته د شروع نه وئيلى وُو او خبردارے مو درکړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28477, '1 Thessalonians 4:7', '1 Thessalonians', 4, 7, '&nbsp;خُدائ پاک مونږ د ناپاکۍ دپاره نه، بلکې د پاکوالى دپاره رابللى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28478, '1 Thessalonians 4:8', '1 Thessalonians', 4, 8, '&nbsp;نو په دې وجه څوک چې دا نۀ منى، نو هغه انسانى حُکمونه نه، بلکې خُدائ پاک نۀ منى چا چې تاسو له خپل روحُ القُدس هم درکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28479, '1 Thessalonians 4:9', '1 Thessalonians', 4, 9, '&nbsp;خو اوس مونږ ته د دې ضرورت نشته چې تاسو ته د ايماندارانو سره د مينې کولو په حقله وليکو ځکه چې خُدائ پاک په خپله تاسو له دا تعليم درکړے دے چې يو بل سره مينه کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28480, '1 Thessalonians 4:10', '1 Thessalonians', 4, 10, '&nbsp;او حقيقت کښې تاسو په ټوله مِکدونيه کښې د ټولو ايماندارانو سره مينه کوئ. خو عزيزانو، مونږ تاسو ته دا خواست کوُو چې خپله مينه نوره هم سېوا کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28481, '1 Thessalonians 4:11', '1 Thessalonians', 4, 11, '&nbsp;په آرام سره ژوند تېرول خپل مقصد جوړ کړئ او په خپل کار کښې مشغول اوسئ او په خپلو لاسونو په کار کسب کښې همت کوئ، څنګه چې مونږ تاسو ته تعليم درکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28482, '1 Thessalonians 4:12', '1 Thessalonians', 4, 12, '&nbsp;نو چې تاسو د غېر ايماندارانو سره په ښۀ طريقه سلوک کوئ او د چا هم محتاج نۀ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28483, '1 Thessalonians 4:13', '1 Thessalonians', 4, 13, '&nbsp;خو اے وروڼو او خوېندو، مونږ دا نۀ غواړو چې تاسو ناخبره پاتې شئ د هغوئ په حقله څوک چې مړۀ دى، نو چې تاسو د هغه نورو په شان غمژن نۀ شئ د چا چې اُميد نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28484, '1 Thessalonians 4:14', '1 Thessalonians', 4, 14, '&nbsp;ځکه چې زمونږ دا ايمان دے چې عيسىٰ مړ شو او بيا ژوندے شو، نو دغه شان به خُدائ پاک هغه څوک هم د عيسىٰ سره واپس راولى څوک چې د هغۀ سره په ايمان مړۀ شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28485, '1 Thessalonians 4:15', '1 Thessalonians', 4, 15, '&nbsp;نو په دې وجه مونږ تاسو ته د مالِک د کلام په مطابق وايو مونږ څوک چې ژوندى يُو، او د مالِک تر راتلو پورې پاتې يُو، مونږ به د هغه چا نه وړاندې د مالِک سره مِلاو نۀ شُو هغه څوک چې مخکښې مړۀ شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28486, '1 Thessalonians 4:16', '1 Thessalonians', 4, 16, '&nbsp;ځکه چې مالِک به په خپله د آسمان نه د اوچت آواز سره، او د مقربې فرښتې د آواز سره، او د خُدائ پاک د بيګل د آواز سره راکوز شى، او په هغۀ کښې مړۀ شوى به اول د قبر نه راپاڅى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28487, '1 Thessalonians 4:17', '1 Thessalonians', 4, 17, '&nbsp;او بيا مونږ څوک چې ژوندى يُو او پاتې يُو به د هغوئ سره يو ځائ په وريځو کښې پورته کړے شُو د دې دپاره چې په هوا کښې د مالِک سره مِلاو شُو، او دغه شان به مونږ تل تر تله د مالِک سره يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28488, '1 Thessalonians 4:18', '1 Thessalonians', 4, 18, '&nbsp;نو ځکه تاسو په دې خبرو سره يو بل له ډاډګيرنه ورکوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28489, '1 Thessalonians 5:1', '1 Thessalonians', 5, 1, '&nbsp;نو اے وروڼو او خوېندو، اوس د هغه وختونو او د موقعو په حقله تاسو ته د څۀ ليکلو حاجت نشته چې دا به کله پېښ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28490, '1 Thessalonians 5:2', '1 Thessalonians', 5, 2, '&nbsp;ځکه چې تاسو په خپله ښۀ خبر يئ چې د مالِک خُدائ د قيامت ورځ به لکه د غل په شان ناګهانه راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28491, '1 Thessalonians 5:3', '1 Thessalonians', 5, 3, '&nbsp;کله چې هغوئ وائى چې، ”امن او سلامتى ده،“ نو ناګهانه به په هغوئ هلاکت راشى لکه څنګه چې په اُميدوارې ښځې د ماشوم پېدا کېدو درد راشى، نو هغه خلق به تښتېدلے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28492, '1 Thessalonians 5:4', '1 Thessalonians', 5, 4, '&nbsp;خو اے وروڼو او خوېندو، تاسو په تيارۀ کښې نۀ يئ د هغه ورځ دپاره چې تاسو به لکه د غل په شان حېران کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28493, '1 Thessalonians 5:5', '1 Thessalonians', 5, 5, '&nbsp;ځکه چې تاسو ټول د نُور او د ورځې بچى يئ، او مونږ نۀ د شپې يُو او نۀ د تيارې يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28494, '1 Thessalonians 5:6', '1 Thessalonians', 5, 6, '&nbsp;نو بيا دې مونږ د نورو په شان اودۀ پاتې نۀ شُو بلکې مونږ دې بېدار او په هوش کښې اوسو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28495, '1 Thessalonians 5:7', '1 Thessalonians', 5, 7, '&nbsp;ځکه څوک چې اودۀ کيږى هغوئ په شپه کښې اودۀ کيږى، او څوک چې نشه کيږى هغوئ په شپه کښې نشه کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28496, '1 Thessalonians 5:8', '1 Thessalonians', 5, 8, '&nbsp;خو مونږ چې د ورځې سره تعلق ساتو نو په کار دى چې مونږ په هوش کښې اوسو، او د ايمان او د مينې زغره واغوندو او د خلاصون د اُميد ټوپۍ په سر کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28497, '1 Thessalonians 5:9', '1 Thessalonians', 5, 9, '&nbsp;ځکه چې خُدائ پاک مونږ د غضب دپاره نۀ يُو مقرر کړى، بلکې د دې دپاره چې مونږ د خپل مالِک عيسىٰ مسيح په وسيله خلاصون بيامومو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28498, '1 Thessalonians 5:10', '1 Thessalonians', 5, 10, '&nbsp;هغه زمونږ دپاره ځکه مړ شو نو کۀ مونږ ژوندى يُو يا کۀ مړۀ، نو مونږ به ټول د هغۀ سره يو ځائ اوسيږو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28499, '1 Thessalonians 5:11', '1 Thessalonians', 5, 11, '&nbsp;نو په دې وجه تاسو يو بل له ډاډ ورکوئ او يو بل جوړوئ، څنګه چې په حقيقت کښې تاسو هم دغه شان کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28500, '1 Thessalonians 5:12', '1 Thessalonians', 5, 12, '&nbsp;خو اے وروڼو او خوېندو، مونږ تاسو ته مِنت کوُو، چې څوک ستاسو په مينځ کښې خوارى کوى او په مالِک کښې ستاسو لار ښودونکى وى او تاسو ته نصيحت کوى د هغوئ قدر کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');